+            fprintf(stderr, "\nOptions:\n");
+            fprintf(stderr, "  -v: display version info and exit\n");
+            fprintf(stderr, "  -h: display this help and exit\n");
+            fprintf(stderr, "  -f: path to a MaxMind Database file\n\n");
+            if (mmdbs) {
